#include <iostream>
#include <map>
#include <string>
int main() {
    std::map<std::string, int> stock{{"pen", 12}, {"book", 5}};
    const auto it = stock.find("pen");
    if (it != stock.end() && it->second > 0) --it->second;
    std::cout << "pens remaining=" << stock.at("pen") << '\n';
}
